import type OpenFin from '@openfin/core';

import * as a11y from '../a11y/speak';
import { applyDeferShowOptions } from '../defer-show';
import { WindowName } from '../window';

/**
 * Default indicator options.
 */
const INDICATOR_OPTIONS: OpenFin.PlatformWindowCreationOptions = applyDeferShowOptions({
    alwaysOnTop: true,
    autoShow: false,
    frame: false,
    resizable: false,
    showTaskbarIcon: false
});

export default function makeShowIndicator(opts: OpenFin.PlatformWindowCreationOptions = INDICATOR_OPTIONS) {
    /**
     * Namespaced indicators that are currently active.
     * Only one indicator for a namespace can be active at once.
     */
    const activeIndicators: Map<string, { currentUrl: string; currentName: string }> = new Map();
    return async (namespace: string, url: string, message: string, type: string, secondaryMessage: string) => {
        if (activeIndicators.has(namespace)) {
            const { currentUrl, currentName } = activeIndicators.get(namespace);
            if (currentUrl === url) return;
            const win = fin.Window.wrapSync({ uuid: fin.me.uuid, name: currentName });
            await win.close();
        }

        const name = `${WindowName.BrowserIndicator}-${Date.now()}${Math.random()}`;
        activeIndicators.set(namespace, { currentUrl: url, currentName: name });
        const a11yMsg = `New ${type} indicator: ${message} ${secondaryMessage}`;
        const activeIndicator = await fin.Platform.getCurrentSync().createWindow({
            ...opts,
            name,
            url
        });
        a11y.speak(a11yMsg);

        activeIndicator.once('closed', () => {
            activeIndicators.delete(namespace);
        });
    };
}
